from typing import List, Protocol, runtime_checkable

@runtime_checkable
class VectorLike(Protocol):
    def __len__(self) -> int: ...
    def __getitem__(self, idx: int) -> float: ...
    def __iter__(self): ...

Vector = List[float]

@runtime_checkable
class MatrixLike(Protocol):
    def __len__(self) -> int: ...
    def __getitem__(self, idx: int) -> Vector: ...

Matrix = List[Vector]
